class ScfcFixerException(Exception):
    """The old exception kept for backward compatibility"""


class ScfcException(ScfcFixerException):
    """Base exception for SCFC-related classes"""


class NoSuchManagedObject(ScfcFixerException):
    """Raised when needed managed object does not exist in SCFC"""


class NoSuchListParameter(ScfcFixerException):
    """Raised when needed list parameter does not exist in SCFC"""


class NoSuchParameter(ScfcFixerException):
    """Raised when needed parameter does not exist in SCFC"""


class ExactlyOneManagedObjectExpected(ScfcFixerException):
    """Raised when managed object does not exist in SCFC or if mutiple managed objects exist when exactly one is expected to exist"""


class DuplicatedDistNames(ScfcFixerException):
    """Raised when managed object has duplicated distName param"""
